/* Download-aware boot screen; the world module reports its real construction milestones. */
(()=>{
const root=document.querySelector('#loading'),phase=document.querySelector('#loading-phase'),number=document.querySelector('#loading-number'),bar=document.querySelector('#loading-bar'),progress=document.querySelector('#loading-progress');let value=0,complete=false;const history=[];let shownPercent=-1,shownStage=-1,shownLabel=null;
function report(next,label){value=Math.max(value,Math.min(100,next));const percent=Math.floor(value),stage=value<40?1:value<57?2:value<68?3:value<84?4:value<90?5:6;if(stage!==shownStage){phase.textContent=String(stage).padStart(2,'0')+' / 06';shownStage=stage;}if(label!==shownLabel){phase.setAttribute('aria-label',label);shownLabel=label;}if(percent!==shownPercent){number.textContent=percent+'%';bar.style.transform=`scaleX(${value/100})`;progress.setAttribute('aria-valuenow',String(percent));shownPercent=percent;}history.push({progress:value,label});}
function fail(error){phase.hidden=false;console.error('City startup failed',error);phase.textContent='The city could not load. Please try again.';document.querySelector('#loading-retry').hidden=false;document.querySelector('#error').hidden=false;}
window.atlasBoot={history,get progress(){return value;},report,async step(next,label){report(next,label);await new Promise(r=>requestAnimationFrame(()=>setTimeout(r,0)));},async finish(){if(complete)return;complete=true;report(100,'Your world is ready');await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));await Promise.all(bar.getAnimations().map(animation=>animation.finished.catch(()=>{})));void window.atlasMusic?.startForReveal();await window.atlasReveal();},fail};
document.querySelector('#loading-retry').onclick=()=>location.reload();report(0,'Preparing your energy world');
async function start(){const manifest=await fetch('./boot-manifest.json').then(r=>{if(!r.ok)throw Error('Loading manifest unavailable');return r.json();});const files=manifest.files,assets=[...files,manifest.audio],expected=assets.reduce((n,f)=>n+f.bytes,0),counts=assets.map(()=>0);const payloads=await Promise.all(assets.map(async(file,index)=>{const response=await fetch('./'+file.path);if(!response.ok)throw Error('Could not load '+file.path);const reader=response.body?.getReader(),chunks=[];if(reader){while(true){const {done,value:chunk}=await reader.read();if(done)break;chunks.push(chunk);counts[index]+=chunk.byteLength;report(Math.min(40,counts.reduce((a,b)=>a+b,0)/expected*40),'Loading the 3D engine, city and music');if(index===files.length)document.querySelector('#loading-music-state').textContent='Loading music '+Math.min(100,Math.floor(counts[index]/file.bytes*100))+'%';}}else{const chunk=new Uint8Array(await response.arrayBuffer());chunks.push(chunk);counts[index]=chunk.length;}const bytes=new Uint8Array(counts[index]);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return index===files.length?bytes.buffer:new TextDecoder().decode(bytes);}));const sources=payloads.slice(0,files.length);await window.atlasMusic.prepare(payloads[files.length]);await window.atlasNarration.prepare();

function blob(source){return URL.createObjectURL(new Blob([source],{type:'text/javascript'}));}const engine=blob(sources[0]),controls=blob(sources[1].replace(/from\s+['"]three['"]/g,`from '${engine}'`)),city=blob(sources[2].replace(/from\s+['"]three['"]/g,`from '${engine}'`).replace("from './vendor/OrbitControls.js'",`from '${controls}'`));report(40,'Constructing the world');await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));try{await import(city);}finally{for(const url of[engine,controls,city])URL.revokeObjectURL(url);}}
const decoders=new Map();function decoderFor(i){if(!decoders.has(i))decoders.set(i,new TextDecoder());return decoders.get(i);}start().catch(fail);
})();



